async function main() {
  console.log('=== Testing feishu_wiki and feishu_doc tools ===\n');

  // Step 1: Get wiki node with token
  console.log('1. Getting wiki node with token: MKJtwW9nriMKh3kMmz4c3Bubnoc');
  try {
    const wiki = getToolByName('feishu_wiki');
    const wikiResult = await wiki({ action: 'get', token: 'MKJtwW9nriMKh3kMmz4c3Bubnoc' });
    console.log('Wiki Result:', JSON.stringify(wikiResult, null, 2));

    if (wikiResult && wikiResult.obj_token) {
      console.log('\n2. Reading document with obj_token:', wikiResult.obj_token);
      const doc = getToolByName('feishu_doc');
      const docResult = await doc({ action: 'read', doc_token: wikiResult.obj_token });
      console.log('Doc Result:', JSON.stringify(docResult, null, 2));
    }
  } catch (e) {
    console.error('Error:', e.message);
  }
}

main();
